package dev.rag.identity;
import dev.rag.common.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class AccessPolicyTest {
 Db db;AccessPolicy policy;
 @BeforeEach void setup(){var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");db=new Db(new NamedParameterJdbcTemplate(ds));for(String ddl:List.of("CREATE TABLE app_user(tenant_id VARCHAR,id VARCHAR,status VARCHAR)","CREATE TABLE knowledge_base(tenant_id VARCHAR,id VARCHAR,status VARCHAR)","CREATE TABLE kb_grant(tenant_id VARCHAR,kb_id VARCHAR,principal_type VARCHAR,user_id VARCHAR,group_id VARCHAR)","CREATE TABLE document(tenant_id VARCHAR,id VARCHAR,kb_id VARCHAR,status VARCHAR,acl_mode VARCHAR,active_build_id VARCHAR)","CREATE TABLE document_grant(tenant_id VARCHAR,document_id VARCHAR,principal_type VARCHAR,user_id VARCHAR,group_id VARCHAR)","CREATE TABLE group_member(tenant_id VARCHAR,user_id VARCHAR,group_id VARCHAR)"))db.exec(ddl,Map.of());db.exec("INSERT INTO app_user VALUES ('t','ops','ACTIVE'),('t','admin','ACTIVE'),('other','ops','ACTIVE')",Map.of());db.exec("INSERT INTO knowledge_base VALUES ('t','kb','LIVE')",Map.of());db.exec("INSERT INTO kb_grant VALUES ('t','kb','GROUP',NULL,'ops-group')",Map.of());db.exec("INSERT INTO group_member VALUES ('t','ops','ops-group')",Map.of());db.exec("INSERT INTO document VALUES ('t','doc','kb','LIVE','RESTRICT','build')",Map.of());db.exec("INSERT INTO document_grant VALUES ('t','doc','USER','ops',NULL)",Map.of());policy=new AccessPolicy(db);}
 @Test void intersectsKbAndDocumentAndNeverBypassesForAdmin(){assertTrue(policy.canReadDocument(new Actor("t","ops",false),"doc"));assertFalse(policy.canReadDocument(new Actor("t","admin",true),"doc"));assertFalse(policy.canReadDocument(new Actor("other","ops",false),"doc"));db.exec("DELETE FROM group_member",Map.of());assertFalse(policy.canReadDocument(new Actor("t","ops",false),"doc"));}
 @Test void deletedDocumentAndDisabledUserExcludedBeforeIndexSearch(){var a=new Actor("t","ops",false);assertEquals(List.of("build"),policy.readableBuilds(a,List.of("kb")));db.exec("UPDATE document SET status='TRASHED'",Map.of());assertTrue(policy.readableBuilds(a,List.of()).isEmpty());assertThrows(ApiException.class,()->policy.guard(a,List.of("doc"),()->"content"));db.exec("UPDATE document SET status='LIVE'",Map.of());db.exec("UPDATE app_user SET status='DISABLED' WHERE id='ops'",Map.of());assertFalse(policy.canReadDocument(a,"doc"));}
}
